contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount, address bob) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);
        require(bob != address(0));
        require(bob != address(this));

        uint before_sender = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint before_bob = c.balances(bob); if (__ESBMC_reverted()) return;

        c.Deposit{value: amount}(); if (__ESBMC_reverted()) return;

        uint after_sender = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint after_bob = c.balances(bob); if (__ESBMC_reverted()) return;

        assert(after_sender == before_sender + amount && after_bob == before_bob);
    }

    receive() external payable {}
}

