pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 amount, address bob) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        vm.assume(bob != address(0));
        vm.assume(bob != address(this));
        uint256 before_sender;
        try c.balances(address(this)) returns (uint256 __r) { before_sender = __r; } catch { return; }
        uint256 before_bob;
        try c.balances(bob) returns (uint256 __r) { before_bob = __r; } catch { return; }
        try c.Deposit{value: amount}() {} catch { return; }
        uint256 after_sender;
        try c.balances(address(this)) returns (uint256 __r) { after_sender = __r; } catch { return; }
        uint256 after_bob;
        try c.balances(bob) returns (uint256 __r) { after_bob = __r; } catch { return; }
        assertTrue(after_sender == before_sender + amount && after_bob == before_bob);
    }

    function testFuzz_run(uint256 amount, address bob) public {
        vm.assume(bob.code.length == 0 && uint160(bob) > 0xffff && bob != address(this) && bob != address(c) && bob != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && bob != 0x000000000000000000636F6e736F6c652e6c6f67 && bob != 0x4e59b44847b379578588920cA78FbF26c0B4956C && bob != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(amount, bob);
    }

    receive() external payable {}
}
